 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            comps.append((color, cells))

    # Find a thin, connected L-shaped color marker.
    markers = []
    for i, (color, cells) in enumerate(comps):
        if color == bg:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        s = set(cells)
        forms = [
            ({(r0, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)}, r0, c0, 1, 1),
            ({(r0, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}, r0, c1, 1, -1),
            ({(r1, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)}, r1, c0, -1, 1),
            ({(r1, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}, r1, c1, -1, -1),
        ]
        for shape, elbow_r, elbow_c, arm_r, arm_c in forms:
            if s == shape and len(cells) >= 5:
                markers.append((len(cells), i, color, elbow_r, elbow_c, arm_r, arm_c))
                break
    if not markers:
        return [row[:] for row in grid]

    _, marker_i, marker_color, er, ec, arm_r, arm_c = max(markers)
    # The intended object is in the open quadrant opposite the two arms.
    candidates = []
    for i, (color, cells) in enumerate(comps):
        if i == marker_i or color == bg:
            continue
        cr = sum(r for r, c in cells) / len(cells)
        cc = sum(c for r, c in cells) / len(cells)
        if (cr < er if arm_r > 0 else cr > er) and (cc < ec if arm_c > 0 else cc > ec):
            candidates.append((len(cells), i))
    if not candidates:
        return [row[:] for row in grid]
    _, target_i = max(candidates)
    out = [row[:] for row in grid]
    for r, c in comps[target_i][1]:
        out[r][c] = marker_color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
